  "eighth",
  "sixteenth",
  "thirtySecond",
];
const VIEWS: readonly ScoreViewMode[] = ["continuous", "page"];
const BACKENDS: readonly BackendSetting[] = ["auto", "basicPitch"];

function num(v: unknown, min: number, max: number): number | null {
  return typeof v === "number" && Number.isFinite(v) && v >= min && v <= max
    ? v
    : null;
}
function str(v: unknown): string | null {
  return typeof v === "string" ? v : null;
}
function bool(v: unknown): boolean | null {
  return typeof v === "boolean" ? v : null;
}
function oneOf<T extends string>(v: unknown, list: readonly T[]): T | null {
  return typeof v === "string" && (list as readonly string[]).includes(v)
    ? (v as T)
    : null;
}

/** Parse + validate the stored blob; unknown/invalid fields get defaults. */
export function parseSettings(raw: string | null): AppSettings {
  if (!raw) return DEFAULT_SETTINGS;
  let o: Record<string, unknown>;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return DEFAULT_SETTINGS;
    o = parsed as Record<string, unknown>;
  } catch {
    return DEFAULT_SETTINGS;
  }
  const d = DEFAULT_SETTINGS;
  return {
    playbackRate: num(o.playbackRate, 0.25, 4) ?? d.playbackRate,
    skipSeconds: num(o.skipSeconds, 1, 60) ?? d.skipSeconds,
    followPlayback: bool(o.followPlayback) ?? d.followPlayback,
    tempoMode: oneOf(o.tempoMode, ["auto", "manual"]) ?? d.tempoMode,
    bpm: num(o.bpm, 30, 300) ?? d.bpm,
    meter: oneOf(o.meter, METERS) ?? d.meter,
    minDuration: oneOf(o.minDuration, MIN_DURATIONS) ?? d.minDuration,
    triplets: bool(o.triplets) ?? d.triplets,
    scoreInitialView: oneOf(o.scoreInitialView, VIEWS) ?? d.scoreInitialView,
    defaultExportDir: str(o.defaultExportDir) ?? d.defaultExportDir,
    museScorePath: str(o.museScorePath) ?? d.museScorePath,
    ffmpegPath: str(o.ffmpegPath) ?? d.ffmpegPath,
    backend: oneOf(o.backend, BACKENDS) ?? d.backend,
  };
}

export function loadSettings(): AppSettings {
  try {
    return parseSettings(window.localStorage.getItem(STORAGE_KEY));
  } catch {
    return DEFAULT_SETTINGS;
  }
}

export function saveSettings(settings: AppSettings): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    /* persistence is best-effort — the session keeps working */
  }
}

/** Valid playback-rate options surfaced in 設定 → 再生. */
export function playbackRateOptions(): readonly number[] {
  return RATES;
}

/**
 * React binding: current settings + a merge-style updater that persists
 * immediately (the theme switcher sets the precedent — changes apply at
 * once, no save button).
 */
export function useAppSettings(): {
  settings: AppSettings;
  update: (patch: Partial<AppSettings>) => void;
} {
  const [settings, setSettings] = useState<AppSettings>(loadSettings);
  const update = useCallback((patch: Partial<AppSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      saveSettings(next);
      return next;
    });
  }, []);
  return useMemo(() => ({ settings, update }), [settings, update]);
}

/**
 * SidecarPort — the transport seam between the typed NDJSON client and a
 * concrete worker process.
 *
 * The port owns process lifecycle only: it delivers whole stdout lines to
 * the client and accepts whole request lines back. It knows nothing about
 * the protocol (no JSON parsing) — that layering mirrors the UI-002 test
 * harness (`WorkerHandle`), which is why the same client runs against the
 * in-process MockSidecarPort and, later, a Tauri-spawned worker unchanged.
 *
 * ## Packaged-app transport (ENG-002)
 *
 * Inside the Tauri webview the worker is spawned by the shell's own
 * `engine` module (src-tauri/src/engine.rs): `engine_spawn` launches
 * `python -m hornscribe.worker` and relays stdout/stderr/exit over a
 * `Channel` — see {@link TauriSidecarPort}. No plugin capability was
 * widened: app-defined commands are not ACL-gated and the spawned
 * program is fixed Rust-side, so the bridge cannot be turned into a
 * general process launcher. `UnsupportedSidecarPort` remains the
 * explicit-failure placeholder for runtimes with no spawn bridge.
 */

import { ERR, SidecarError } from "./protocol";
import { MockSidecarPort } from "./mockPort";
import { TauriSidecarPort } from "./tauriPort";
import { isTauriRuntime } from "../tauri/bridge";

export interface SidecarPort {
  /**
   * Spawn/attach the worker. Resolves when the process is up and its
   * stdin is writable — the protocol handshake happens after this, on the
   * client. Rejects when the worker cannot be launched at all.
   */
  start(): Promise<void>;
  /** Write one NDJSON frame to the worker's stdin (a newline is appended). */
  writeLine(line: string): void;
  /**
   * Close the worker's stdin — the worker treats EOF as an implicit
   * graceful `engine.shutdown` (worker.py contract).
   */
  closeStdin(): void;
  /**
   * Terminate the worker immediately. This is the documented
   * terminate/restart fallback for non-interruptible jobs and the
   * unresponsive-worker path (ENGINE_RUNTIME_MATRIX / ADR-0002).
   */
  kill(): void;
  /** Subscribe to raw stdout lines. Returns an unsubscribe function. */
  onLine(cb: (line: string) => void): () => void;
  /** Subscribe to stderr lines (diagnostics only, never protocol). */
  onStderr(cb: (line: string) => void): () => void;
  /**
   * Subscribe to process exit. Fires exactly once. `code` is the exit
   * code, or null when it cannot be determined (e.g. killed by signal).
   */
  onExit(cb: (code: number | null) => void): () => void;
}

/**
 * Placeholder port for environments where no spawn bridge exists.
 * `start()` fails explicitly with ENGINE_UNAVAILABLE; the session maps
 * that to the worker-not-responding recovery surface, so the shell
 * degrades honestly instead of pretending a mock engine is real.
 */
export class UnsupportedSidecarPort implements SidecarPort {
  async start(): Promise<void> {
    throw new SidecarError(
      ERR.ENGINE_UNAVAILABLE,
      "engine sidecar spawn is not wired into the Tauri shell yet " +
        "(requires a process bridge; see src/sidecar/README.md)",
    );
  }
  writeLine(): void {
    throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "sidecar port is unavailable");
  }
  closeStdin(): void {
    /* no worker */
  }
  kill(): void {
    /* no worker */
  }
  onLine(): () => void {
    return () => undefined;
  }
  onStderr(): () => void {
    return () => undefined;
  }
  onExit(): () => void {
    return () => undefined;
  }
}

/**
 * The port used when no explicit one is injected:
 * - inside the Tauri webview: {@link TauriSidecarPort} (ENG-002 — the
 *   Rust engine supervisor spawns `python -m hornscribe.worker`);
 * - in a plain browser (`vite dev`): {@link MockSidecarPort}, an
 *   in-process emulation of `python -m hornscribe.worker` that speaks the
 *   real NDJSON contract so the whole transcription UX is exercisable
 *   without a Python runtime.
 */
export function createDefaultSidecarPort(): SidecarPort {
  if (isTauriRuntime()) return new TauriSidecarPort();
  return new MockSidecarPort();
}

/**
 * Client-side mirror of the HornScribe NDJSON sidecar protocol
 * (protocol/PROTOCOL.md, implemented engine-side by
 * python/hornscribe/worker/protocol.py).
 *
 * Transport: one JSON envelope per line over the sidecar's stdin/stdout;
 * stderr is diagnostics only. Unknown additive fields are ignored safely
 * (ADR-0002), so every payload type below carries an index signature.
 */

/** Wire protocol version implemented by this client. */
export const PROTOCOL_VERSION = 1;

/** Structured error object carried inside an envelope or a job event. */
export interface ProtocolErrorObject {
  code: string;
  message: string;
  details?: unknown;
}

export type FrameKind = "request" | "response" | "event";

/** The wire envelope — a single JSON object per NDJSON line. */
export interface Envelope {
  v: number;
  id: string | null;
  kind: FrameKind;
  method: string | null;
  payload: unknown;
  error: ProtocolErrorObject | null;
}

/**
 * Error codes. UPPER_SNAKE per PROTOCOL.md. The first block mirrors
 * python/hornscribe/worker/protocol.py exactly; the second block is
 * shell-side supervision codes that never appear on the wire — they mark
 * failures the supervisor (this client) detected itself, mirroring how the
 * UI-002 test harness marks an in-flight job failed when the worker dies
 * mid-job (ADR-0002: never silently resubmitted).
 */
export const ERR = {
  PROTOCOL_VERSION_MISMATCH: "PROTOCOL_VERSION_MISMATCH",
  MALFORMED_MESSAGE: "MALFORMED_MESSAGE",
  UNKNOWN_METHOD: "UNKNOWN_METHOD",
  INVALID_PARAMS: "INVALID_PARAMS",
  JOB_NOT_FOUND: "JOB_NOT_FOUND",
  JOB_ALREADY_RUNNING: "JOB_ALREADY_RUNNING",
  UNKNOWN_JOB_KIND: "UNKNOWN_JOB_KIND",
  JOB_TIMEOUT: "JOB_TIMEOUT",
  JOB_FAILED: "JOB_FAILED",
  INTERNAL_ERROR: "INTERNAL_ERROR",
  // ---- wire codes added by the real engine (ENG-002) ----
  /** The worker is up but a required engine package is missing. */
  ENGINE_DEPENDENCY_MISSING: "ENGINE_DEPENDENCY_MISSING",
  /** The pipeline found no pitched notes — a content outcome, not a crash. */
  NO_PITCHED_CONTENT: "NO_PITCHED_CONTENT",
  // ---- shell-side supervision codes (not wire codes) ----
  /** The worker process exited without a graceful shutdown. */
  WORKER_CRASHED: "WORKER_CRASHED",
  /** Watchdog: the worker stopped answering while a job was in flight. */
  WORKER_UNRESPONSIVE: "WORKER_UNRESPONSIVE",
  /** A request received no response within its timeout. */
  REQUEST_TIMEOUT: "REQUEST_TIMEOUT",
  /** The sidecar transport could not be started (e.g. spawn gate). */
  ENGINE_UNAVAILABLE: "ENGINE_UNAVAILABLE",
  /** A request was issued while the client was not in `ready` state. */
  ENGINE_NOT_READY: "ENGINE_NOT_READY",
} as const;

export type ErrorCode = (typeof ERR)[keyof typeof ERR];

/** Structured failure raised by the client — converts an error object to
 *  an exception so callers can `catch` instead of checking envelopes. */
export class SidecarError extends Error {
  readonly code: string;
  readonly details?: unknown;

  constructor(code: string, message: string, details?: unknown) {
    super(message);
    this.name = "SidecarError";
    this.code = code;
    this.details = details;
  }
}

// ---- envelope builders (client → worker) -----------------------------

export function requestFrame(
  id: string,
  method: string,
  payload: unknown,
): Envelope {
  return { v: PROTOCOL_VERSION, id, kind: "request", method, payload, error: null };
}

/** Serialize an envelope to a single NDJSON line (no trailing newline —
 *  the port adds it). JSON.stringify escapes control characters so the
 *  output can never contain a raw newline. */
export function encodeFrame(envelope: Envelope): string {
  return JSON.stringify(envelope);
}

// ---- inbound parsing ---------------------------------------------------

/**
 * Parse one inbound NDJSON line into an Envelope, or return null when the
 * frame is too malformed to use. Client-side parsing is deliberately
 * tolerant about *content* (unknown fields pass through per ADR-0002) but
 * strict about envelope shape: a frame we cannot route is dropped and
 * reported through the diagnostics channel, never answered.
 */
export function parseInboundFrame(line: string): Envelope | null {
  const text = line.trim();
  if (!text) return null;
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return null;
  }
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    return null;
  }
  const frame = raw as Record<string, unknown>;
  if (frame.v !== PROTOCOL_VERSION) return null;
  const kind = frame.kind;
  if (kind !== "response" && kind !== "event") {
    // The worker only ever sends responses and events; anything else
    // (including inbound "request") is logged and dropped, never answered.
    return null;
  }
  const id = frame.id;
  const method = frame.method;
  if (kind === "response") {
    // A response carries the request id — except the single sanctioned
    // `id: null` case (worker could not recover an id from our frame),
    // which also arrives with `method: null`.
    if (id !== null && (typeof id !== "string" || !id)) return null;
    if (id === null) {
      if (method !== null && method !== undefined && typeof method !== "string") {
        return null;
      }
    } else if (typeof method !== "string" || !method) {
      return null;
    }
  } else {
    // Events must carry exactly `id: null` and a non-empty method.
    if (id !== null) return null;
    if (typeof method !== "string" || !method) return null;
  }
  const error = normalizeError(frame.error);
  return {
    v: PROTOCOL_VERSION,
    id: (id as string | null) ?? null,
    kind,
    // `undefined` (absent field) normalizes to null — the wire contract
    // always carries the key, but a tolerantly-typed frame may omit it.
    method: (method as string | null | undefined) ?? null,
    payload: frame.payload,
    error,
  };
}

function normalizeError(raw: unknown): ProtocolErrorObject | null {
  if (raw === null || raw === undefined) return null;
  if (typeof raw !== "object") return null;
  const e = raw as Record<string, unknown>;
  if (typeof e.code !== "string" || typeof e.message !== "string") return null;
  return { code: e.code, message: e.message, details: e.details };
}

// ---- method payloads -----------------------------------------------------

export interface EngineInfo {
  name?: string;
  version?: string;
  python?: string;
  platform?: string;
  pid?: number;
  [key: string]: unknown;
}

export interface EngineCapabilities {
  methods?: string[];
  jobKinds?: string[];
  maxConcurrentJobs?: number;
  cooperativeCancel?: boolean;
  cancellationFallback?: string;
  progressEvents?: boolean;
  basicPitchAvailable?: boolean;
  [key: string]: unknown;
}

export interface HandshakeResult {
  protocolVersion: number;
  engineInfo: EngineInfo;
  capabilities: EngineCapabilities;
  [key: string]: unknown;
}

export interface PingResult {
  echo: unknown;
  workerPid?: number;
  uptimeMs?: number;
  [key: string]: unknown;
}

export interface ShutdownResult {
  ok: boolean;
  activeJob: string | null;
  [key: string]: unknown;
}

export interface JobStartResult {
  jobId: string;
  jobKind: string;
  state: string;
  [key: string]: unknown;
}

export interface JobCancelResult {
  jobId: string;
  cancellation: string;
  [key: string]: unknown;
}

/** `job.event` terminal phases: exactly one ends every job. */
export type JobTerminalPhase = "completed" | "cancelled" | "failed";
export type JobPhase = "started" | "progress" | JobTerminalPhase;

/**
 * `job.event` payload (kind=event, id=null).
 *
 * [UI-040] additive fields beyond the UI-002 spike contract:
 * - `stage`: pipeline stage id (TRANSCRIPTION_STAGE_IDS) reported by jobs
 *   that can name their position honestly. Absent for stage-less jobs
 *   (e.g. `demoLongTask` on the spike worker) — the UI must not infer one.
 * - `result.reviewIssues` on `completed`: ReviewIssue dicts
 *   (python/hornscribe/domain/review.py `ReviewIssue.to_dict`).
 */
export interface JobEventPayload {
  jobId: string;
  jobKind?: string;
  phase: JobPhase;
  /** Real 0–1 job fraction when the engine can compute one — may be absent. */
  progress?: number;
  /** [UI-040] current pipeline stage id — absent when unknown. */
  stage?: string;
  step?: number;
  totalSteps?: number;
  /** `failed` terminal events carry the job error here (envelope error stays null). */
  error?: ProtocolErrorObject;
  /** `completed` events may carry the job result payload. */
  result?: unknown;
  [key: string]: unknown;
}

export function isTerminalPhase(phase: string): phase is JobTerminalPhase {
  return phase === "completed" || phase === "cancelled" || phase === "failed";
}

/**
 * TauriSidecarPort — the production {@link SidecarPort} for the packaged
 * shell (ENG-002).
 *
 * The Rust `engine` module (src-tauri/src/engine.rs) owns the process:
 * `engine_spawn` launches `python -m hornscribe.worker` (interpreter
 * resolved via HORNSCRIBE_PYTHON -> repo venvs -> PATH) and streams its
 * stdout/stderr/exit over a {@link Channel}. App-defined commands are
 * not capability-gated, so no ACL/plugin grant is needed — the same
 * self-limiting pattern as `read_audio_bytes` (the frontend cannot pick
 * the program; Rust always spawns the fixed worker module).
 *
 * Channel messages (one JSON object each):
 *   {kind:"line",   line} -> onLine subscribers
 *   {kind:"stderr", line} -> onStderr subscribers
 *   {kind:"exit",   code} -> onExit subscribers (fires exactly once)
 */

import { Channel, invoke } from "@tauri-apps/api/core";
import { ERR, SidecarError } from "./protocol";
import type { SidecarPort } from "./port";

interface EngineChannelMessage {
  kind: "line" | "stderr" | "exit";
  line?: string;
  code?: number | null;
}

export class TauriSidecarPort implements SidecarPort {
  private readonly lineCbs = new Set<(line: string) => void>();
  private readonly stderrCbs = new Set<(line: string) => void>();
  private readonly exitCbs = new Set<(code: number | null) => void>();
  private exitFired = false;
  private running = false;

  async start(): Promise<void> {
    const channel = new Channel<EngineChannelMessage>((msg) => {
      switch (msg.kind) {
        case "line":
          if (typeof msg.line === "string") {
            for (const cb of [...this.lineCbs]) cb(msg.line);
          }
          break;
        case "stderr":
          if (typeof msg.line === "string") {
            for (const cb of [...this.stderrCbs]) cb(msg.line);
          }
          break;
        case "exit":
          this.fireExit(msg.code ?? null);
          break;
      }
    });
    try {
      await invoke("engine_spawn", { channel });
    } catch (e) {
      // Spawn failure (no Python, ENGINE_ALREADY_RUNNING) is surfaced
      // as ENGINE_UNAVAILABLE so the session maps it to the
      // worker-not-responding recovery surface — never a silent mock.
      throw new SidecarError(
        ERR.ENGINE_UNAVAILABLE,
        e instanceof Error ? e.message : String(e),
      );
    }
    this.running = true;
  }

  writeLine(line: string): void {
    if (!this.running) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "engine is not running");
    }
    // invoke is async but fire-and-forget here: write ordering is
    // preserved because Tauri serializes each invoke on the same IPC
    // queue, and a dead worker surfaces via the exit message anyway.
    void invoke("engine_write", { line }).catch(() => {
      /* a write into a dead pipe is reported by the exit event */
    });
  }

  closeStdin(): void {
    if (!this.running) return;
    void invoke("engine_close_stdin").catch(() => undefined);
  }

  kill(): void {
    if (!this.running) return;
    void invoke("engine_kill").catch(() => undefined);
  }

  onLine(cb: (line: string) => void): () => void {
    this.lineCbs.add(cb);
    return () => this.lineCbs.delete(cb);
  }
  onStderr(cb: (line: string) => void): () => void {
    this.stderrCbs.add(cb);
    return () => this.stderrCbs.delete(cb);
  }
  onExit(cb: (code: number | null) => void): () => void {
    this.exitCbs.add(cb);
    return () => this.exitCbs.delete(cb);
  }

  private fireExit(code: number | null): void {
    if (this.exitFired) return; // contract: fires exactly once
    this.exitFired = true;
    this.running = false;
    for (const cb of [...this.exitCbs]) cb(code);
  }
}

"""HornScribe engine sidecar worker (UI-002 spike).

Speaks the NDJSON protocol in ``protocol/PROTOCOL.md`` over stdin/stdout:
stdout carries protocol frames only, all diagnostics go to stderr.

Lifecycle contract (ADR-0002):

- requests are dispatched sequentially on the stdin read loop
- jobs run on daemon threads so the loop stays responsive (progress
  events stream while ``engine.ping`` etc. keep answering)
- ``engine.shutdown`` replies, then the worker exits 0
- stdin EOF is an implicit graceful shutdown (also exit 0)
- an incompatible ``engine.handshake`` protocol version is refused with
  ``PROTOCOL_VERSION_MISMATCH`` and the worker exits — it will not serve
  a peer it cannot talk to
- at most one job is in flight (``JOB_ALREADY_RUNNING``); the spike does
  not need a pool before evidence requires it (issue non-goals)
"""

from __future__ import annotations

import argparse
import contextlib
import importlib.util
import logging
import os
import platform
import sys
import threading
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any, TextIO

import hornscribe
from hornscribe.transcription import (
    JOB_KIND_TRANSCRIPTION,
    TranscriptionParams,
    run_transcription_job,
)
from hornscribe.worker import protocol
from hornscribe.worker.jobs import (
    JOB_KIND_DEMO_LONG_TASK,
    DemoLongTaskParams,
    run_demo_long_task,
)

# Job kinds this worker accepts. ``transcription`` (ENG-002) is the real
# pipeline; ``demoLongTask`` stays for protocol/regression tests.
SUPPORTED_JOB_KINDS: tuple[str, ...] = (
    JOB_KIND_TRANSCRIPTION,
    JOB_KIND_DEMO_LONG_TASK,
)

log = logging.getLogger("hornscribe.worker")

_SHUTDOWN_JOIN_TIMEOUT_S = 2.0


@dataclass
class _Job:
    """Handle for one in-flight job thread."""

    job_id: str
    kind: str
    cancel: threading.Event
    done: threading.Event = field(default_factory=threading.Event)
    thread: threading.Thread | None = None


class Worker:
    """The sidecar process: sequential requests, threaded jobs."""

    def __init__(self, stdin: TextIO, stdout: TextIO) -> None:
        self._stdin = stdin
        self._stdout = stdout
        self._write_lock = threading.Lock()
        self._shutdown = threading.Event()
        self._exit_after_response = False
        self._job: _Job | None = None
        self._job_counter = 0
        self._started = time.monotonic()
        self._methods: dict[str, Callable[[Any], dict[str, Any]]] = {
            "engine.handshake": self._handle_handshake,
            "engine.ping": self._handle_ping,
            "engine.shutdown": self._handle_shutdown,
            "job.start": self._handle_job_start,
            "job.cancel": self._handle_job_cancel,
            # Spike-only supervisor test hook: wedges the dispatch loop so
            # the supervisor-side read timeout path can be exercised.
            # Not a stable API; gated on the "debug." prefix.
            "debug.hang": self._handle_debug_hang,
            # Stack dump of every thread (diagnostics for a stalled job).
            "debug.stacks": self._handle_debug_stacks,
        }

    # ---- frame IO -----------------------------------------------------

    def _send(self, envelope: protocol.Envelope) -> None:
        line = protocol.encode_message(envelope)
        with self._write_lock:
            self._stdout.write(line + "\n")
            self._stdout.flush()

    def _respond(self, request_id: str, method: str | None, payload: Any) -> None:
        self._send(protocol.make_response(request_id, method, payload))

    def _respond_error(
        self,
        request_id: str | None,
        method: str | None,
        code: str,
        message: str,
        details: dict[str, Any] | None = None,
    ) -> None:
        self._send(
            protocol.make_error_response(
                request_id, code, message, details=details, method=method
            )
        )

    def _emit_event(self, method: str, payload: dict[str, Any]) -> None:
        self._send(protocol.make_event(method, payload))

    # ---- main loop ----------------------------------------------------

    def serve(self) -> int:
        """Run the read/dispatch loop until shutdown or stdin EOF."""
        log.info(
            "sidecar started pid=%d protocol=v%d hornscribe=%s",
            os.getpid(),
            protocol.PROTOCOL_VERSION,
            hornscribe.__version__,
        )
        while not self._shutdown.is_set():
            line = self._stdin.readline()
            if line == "":
                log.info("stdin EOF; shutting down")
                break
            self._handle_line(line)
            if self._exit_after_response:
                break
        self._shutdown_gracefully()
        log.info("sidecar stopped")
        return 0

    def _shutdown_gracefully(self) -> None:
        job = self._job
        if job is not None and not job.done.is_set():
            log.info("cancelling active job %s for shutdown", job.job_id)
            job.cancel.set()
            if job.thread is not None:
                job.thread.join(timeout=_SHUTDOWN_JOIN_TIMEOUT_S)

    def _handle_line(self, line: str) -> None:
        try:
            msg = protocol.parse_message(line)
        except protocol.ProtocolError as exc:
            log.warning("rejected inbound frame: %s", exc)
            self._respond_error(exc.request_id, None, exc.code, exc.message, exc.details)
            return
        if msg.kind != protocol.KIND_REQUEST:
            # The peer only ever sends requests. Inbound responses/events
            # are logged and dropped — never answered — to avoid any
            # chance of a reply loop.
            log.warning("ignoring inbound %s frame id=%s", msg.kind, msg.id)
            return
        assert msg.id is not None
        assert msg.method is not None
        handler = self._methods.get(msg.method)
        if handler is None:
            self._respond_error(
                msg.id,
                msg.method,
                protocol.ERR_UNKNOWN_METHOD,
                f"unknown method {msg.method!r}",
                details={"methods": sorted(self._methods)},
            )
            return
        try:
            payload = handler(msg.payload)
        except protocol.ProtocolError as exc:
            self._respond_error(msg.id, msg.method, exc.code, exc.message, exc.details)
            return
        except Exception:
            # Errors are structured data, never raw tracebacks (ADR-0002);
            # the traceback stays on stderr where diagnostics belong.
            log.exception("handler failed for %s", msg.method)
            self._respond_error(
                msg.id, msg.method, protocol.ERR_INTERNAL, "internal worker error"
            )
            return
        self._respond(msg.id, msg.method, payload)

    # ---- method handlers ----------------------------------------------

    def _handle_handshake(self, payload: Any) -> dict[str, Any]:
        params = payload if isinstance(payload, dict) else {}
        client_v = params.get("protocolVersion", protocol.PROTOCOL_VERSION)
        if client_v != protocol.PROTOCOL_VERSION:
            # Refuse explicitly, then exit: a worker that cannot speak the
            # peer's version must not limp along (ADR-0002).
            self._exit_after_response = True
            raise protocol.ProtocolError(
                protocol.ERR_PROTOCOL_VERSION_MISMATCH,
                f"client requested protocol v{client_v!r}; "
                f"worker speaks v{protocol.PROTOCOL_VERSION}",
                details={
                    "requested": client_v,
                    "supported": [protocol.PROTOCOL_VERSION],
                },
            )
        return {
            "protocolVersion": protocol.PROTOCOL_VERSION,
            "engineInfo": {
                "name": "hornscribe-engine",
                "version": hornscribe.__version__,
                "python": platform.python_version(),
                "platform": sys.platform,
                "pid": os.getpid(),
            },
            "capabilities": {
                "methods": sorted(self._methods),
                "jobKinds": list(SUPPORTED_JOB_KINDS),
                "maxConcurrentJobs": 1,
                "cooperativeCancel": True,
                "cancellationFallback": "terminate+restart",
                "progressEvents": True,
                "basicPitchAvailable": importlib.util.find_spec("basic_pitch") is not None,
            },
        }

    def _handle_ping(self, payload: Any) -> dict[str, Any]:
        echo = payload.get("echo") if isinstance(payload, dict) else None
        return {
            "echo": echo,
            "workerPid": os.getpid(),
            "uptimeMs": round((time.monotonic() - self._started) * 1000.0, 1),
        }

    def _handle_shutdown(self, payload: Any) -> dict[str, Any]:
        self._exit_after_response = True
        active = self._active_job()
        return {"ok": True, "activeJob": active.job_id if active else None}

    def _handle_job_start(self, payload: Any) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.start payload must be an object"
            )
        kind = payload.get("jobKind")
        if not isinstance(kind, str) or not kind:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.start requires a string 'jobKind'"
            )
        if kind not in SUPPORTED_JOB_KINDS:
            raise protocol.ProtocolError(
                protocol.ERR_UNKNOWN_JOB_KIND,
                f"unsupported jobKind {kind!r}",
                details={"supported": list(SUPPORTED_JOB_KINDS)},
            )
        active = self._active_job()
        if active is not None:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_ALREADY_RUNNING,
                "a job is already running",
                details={"activeJobId": active.job_id, "maxConcurrentJobs": 1},
            )
        self._job_counter += 1
        job_id = f"job-{self._job_counter:04d}"
        if kind == JOB_KIND_TRANSCRIPTION:
            try:
                tparams = TranscriptionParams.from_payload(payload.get("params"))
            except ValueError as exc:
                raise protocol.ProtocolError(
                    protocol.ERR_INVALID_PARAMS, str(exc)
                ) from exc
            _warm_engine_imports()
            self._job = self._start_transcription_job(job_id, tparams)
        else:
            try:
                params = DemoLongTaskParams.from_payload(payload.get("params"))
            except ValueError as exc:
                raise protocol.ProtocolError(
                    protocol.ERR_INVALID_PARAMS, str(exc)
                ) from exc
            self._job = self._start_demo_job(job_id, params)
        return {"jobId": job_id, "jobKind": kind, "state": "accepted"}

    def _handle_job_cancel(self, payload: Any) -> dict[str, Any]:
        job_id = payload.get("jobId") if isinstance(payload, dict) else None
        if not isinstance(job_id, str) or not job_id:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.cancel requires a string 'jobId'"
            )
        job = self._job
        if job is None or job.done.is_set() or job.job_id != job_id:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_NOT_FOUND, f"no active job {job_id!r}"
            )
        job.cancel.set()
        return {"jobId": job.job_id, "cancellation": "requested"}

    def _handle_debug_hang(self, payload: Any) -> dict[str, Any]:
        seconds = 5.0
        if isinstance(payload, dict):
            raw = payload.get("seconds")
            if isinstance(raw, (int, float)) and not isinstance(raw, bool):
                seconds = float(raw)
        seconds = min(max(seconds, 0.0), 300.0)
        log.warning("debug.hang: wedging dispatch loop for %.1fs", seconds)
        time.sleep(seconds)
        return {"sleptSeconds": seconds}

    def _handle_debug_stacks(self, payload: Any) -> dict[str, Any]:
        """Return a text dump of all thread stacks (job debugging).

        Read-only; used to diagnose a job that appears stuck (e.g. an
        import deadlock in a daemon thread). Not a stable API.
        """
        import traceback

        frames = sys._current_frames()
        out: list[str] = []
        for tid, frame in frames.items():
            out.append(f"--- thread {tid} ---")
            out.extend(traceback.format_stack(frame))
        return {"threads": len(frames), "dump": "".join(out)}

    # ---- jobs ----------------------------------------------------------

    def _active_job(self) -> _Job | None:
        job = self._job
        if job is not None and not job.done.is_set():
            return job
        return None

    def _start_demo_job(self, job_id: str, params: DemoLongTaskParams) -> _Job:
        job = _Job(job_id=job_id, kind=JOB_KIND_DEMO_LONG_TASK, cancel=threading.Event())

        def emit(phase: str, **fields: Any) -> None:
            body: dict[str, Any] = {
                "jobId": job_id,
                "jobKind": JOB_KIND_DEMO_LONG_TASK,
                "phase": phase,
            }
            body.update(fields)
            self._emit_event("job.event", body)

        def run() -> None:
            try:
                run_demo_long_task(
                    job_id=job_id, params=params, emit=emit, cancel=job.cancel
                )
            except Exception:
                log.exception("job %s crashed", job_id)
                emit(
                    "failed",
                    error={
                        "code": protocol.ERR_INTERNAL,
                        "message": "job crashed unexpectedly",
                    },
                )
            finally:
                job.done.set()

        job.thread = threading.Thread(target=run, name=f"{job_id}", daemon=True)
        job.thread.start()
        return job

    def _start_transcription_job(
        self, job_id: str, params: TranscriptionParams
    ) -> _Job:
        job = _Job(
            job_id=job_id, kind=JOB_KIND_TRANSCRIPTION, cancel=threading.Event()
        )

        def emit(phase: str, **fields: Any) -> None:
            body: dict[str, Any] = {
                "jobId": job_id,
                "jobKind": JOB_KIND_TRANSCRIPTION,
                "phase": phase,
            }
            body.update(fields)
            self._emit_event("job.event", body)

        def run() -> None:
            try:
                run_transcription_job(
                    job_id=job_id, params=params, emit=emit, cancel=job.cancel
                )
            except Exception:
                log.exception("job %s crashed", job_id)
                emit(
                    "failed",
                    error={
                        "code": protocol.ERR_INTERNAL,
                        "message": "job crashed unexpectedly",
                    },
                )
            finally:
                job.done.set()

        job.thread = threading.Thread(target=run, name=f"{job_id}", daemon=True)
        job.thread.start()
        return job


def _warm_engine_imports() -> None:
    # Import the native engine stack on the main thread (ENG-002).
    # Loading numpy/onnxruntime DLLs for the first time from a non-main
    # thread can wedge inside create_module on Windows (loader-lock
    # interaction). Importing here — before the job thread starts —
    # makes the job thread hit sys.modules instead. Missing packages
    # are ignored: the job itself reports ENGINE_DEPENDENCY_MISSING
    # with the proper error code.
    # librosa is a lazy_loader package: importing the top level does NOT
    # pull the submodules the pipeline touches, so name them explicitly.
    for name in ("librosa.core.audio", "librosa.beat", "basic_pitch.inference"):
        try:
            importlib.import_module(name)
        except Exception:
            log.debug("engine warm-up import of %s failed", name, exc_info=True)
            break


def _reconfigure_stream(stream: TextIO, **kwargs: Any) -> None:
    """Best-effort ``TextIOWrapper.reconfigure`` (absent on odd streams)."""
    reconfigure = getattr(stream, "reconfigure", None)
    if callable(reconfigure):
        with contextlib.suppress(OSError, ValueError):
            reconfigure(**kwargs)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="hornscribe.worker",
        description="HornScribe engine sidecar (NDJSON over stdio; logs on stderr)",
    )
    parser.add_argument(
        "--version",
        action="version",
        version=(
            f"hornscribe-engine {hornscribe.__version__} "
            f"(protocol v{protocol.PROTOCOL_VERSION})"
        ),
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="store_true",
        help="debug-level diagnostics on stderr",
    )
    args = parser.parse_args(argv)
    logging.basicConfig(
        stream=sys.stderr,
        level=logging.DEBUG if args.verbose else logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
    # stdout is protocol-only: pin UTF-8 + '\n' so a Windows console
    # encoding or newline translation can never corrupt a frame.
    _reconfigure_stream(sys.stdout, encoding="utf-8", newline="\n", write_through=True)
    _reconfigure_stream(sys.stdin, encoding="utf-8")
    return Worker(sys.stdin, sys.stdout).serve()


if __name__ == "__main__":
    raise SystemExit(main())
